previewCss:
.darma-loader-darma-b12-escalator-steps { --accent: var(--loader-color, #14b8a6); --accent-2: var(--loader-secondary-color, #0ea5e9); width: var(--loader-size, 108px); height: calc(var(--loader-size, 108px) * .72); position: relative; overflow: hidden; }
.darma-loader-darma-b12-escalator-steps::after { content: ''; position: absolute; left: 2%; bottom: 14%; width: 104%; height: 5%; border-radius: 999px; background: #cbd5e1; transform-origin: left center; transform: rotate(-37.6deg); }
.darma-loader-darma-b12-escalator-steps span { position: absolute; left: 0; bottom: 4%; width: 22%; height: 12%; border-radius: 3px; background: linear-gradient(var(--accent), var(--accent-2)); animation: darma-loader-darma-b12-escalator-steps-escalate calc(var(--loader-speed, 1s) * 2.4) linear infinite; }
.darma-loader-darma-b12-escalator-steps span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * -.48); }
.darma-loader-darma-b12-escalator-steps span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * -.96); }
.darma-loader-darma-b12-escalator-steps span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * -1.44); }
.darma-loader-darma-b12-escalator-steps span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * -1.92); }
@keyframes darma-loader-darma-b12-escalator-steps-escalate { 0% { opacity: 0; transform: translate(0, 0); } 14% { opacity: 1; } 86% { opacity: 1; } 100% { opacity: 0; transform: translate(calc(var(--loader-size, 108px) * .76), calc(var(--loader-size, 108px) * -.58)); } }

